// Generated by Cypress Author on 2026-10-27 for IMP-06.02.
// Real LAB TEST persistence. Transport-loss injection discards a committed response only.
import type { Session } from '@supabase/supabase-js';
import { pressEnterInChrome, pressKeyInChrome } from './keyboard';

type Fixture = {
  organizationId: string;
  exerciseId: string;
  adminId: string;
  teacherId: string;
  currentVersionId: string;
};
type Context = Fixture & { admin: Session };
type Snapshot = Record<string, { count: number; digest: string }>;
type Result = {
  status: number;
  data: { revision: number; visibility: string; owner: { id: string } };
};
const sel = (name: string) => `[data-cy="${name}"]`;
const detail = '[data-testid="bank-detail-ready"]';
function prepare() {
  return cy
    .task<Fixture>(
      'bank-governance:prepare',
      {},
      { log: false, timeout: 120000 },
    )
    .then((fixture) =>
      cy
        .task<Session>('identity:login', 'ADMIN', { log: false })
        .then((admin) => cy.wrap({ ...fixture, admin }, { log: false })),
    );
}
function visit(c: Context, beforeLoad?: (window: Cypress.AUTWindow) => void) {
  cy.visit(`/administracion/organizaciones/${c.organizationId}/banco`, {
    onBeforeLoad(window) {
      window.localStorage.setItem(
        'alunza.auth.127.0.0.1:18421',
        JSON.stringify(c.admin),
      );
      beforeLoad?.(window);
    },
  });
  cy.get(`[data-cy="exercise-bank-row"][data-exercise-id="${c.exerciseId}"]`)
    .contains('button', 'Ver detalle')
    .click();
  cy.get(detail).should('contain.text', '25 de 25 versiones');
}
function chooseOwner(c: Context) {
  cy.get(sel('bank-governance-open')).click();
  cy.get(`${sel('bank-owner')} option[value="${c.adminId}"]`).should('exist');
  cy.get(sel('bank-owner')).select(c.adminId);
}
function confirmGovernance() {
  cy.get(sel('bank-governance-review')).click();
  cy.get(sel('bank-governance-confirm')).click();
}

describe('IMP-06.02 · Gobierno administrativo del banco', () => {
  it('IMP06-GOV-01 · Revisar y cancelar cambios de acceso/archivo → no muta; confirmar persiste y devuelve foco', () => {
    prepare().then((c) => {
      let patches = 0,
        archives = 0;
      cy.intercept(
        'PATCH',
        `**/api/v1/exercises/${c.exerciseId}/governance`,
        (request) => {
          patches++;
          request.continue();
        },
      ).as('govern');
      cy.intercept(
        'POST',
        `**/api/v1/exercises/${c.exerciseId}/archive`,
        (request) => {
          archives++;
          request.continue();
        },
      );
      cy.task<Snapshot>('bank-governance:snapshot', c, { log: false }).then(
        (before) => {
          visit(c);
          chooseOwner(c);
          cy.get(sel('bank-visibility')).select('PRIVATE');
          cy.get(sel('bank-governance-review')).click();
          cy.get(sel('bank-governance-confirmation'))
            .should('contain.text', 'Administrador A')
            .and('contain.text', 'Privado');
          for (const size of [
            { name: 'desktop', width: 1440, height: 900 },
            { name: 'tablet', width: 768, height: 1024 },
            { name: 'mobile', width: 390, height: 844 },
          ]) {
            cy.viewport(size.width, size.height);
            cy.get('[role="dialog"]').should('be.visible');
            cy.document().should((document) => {
              expect(document.documentElement.scrollWidth).to.be.at.most(
                document.documentElement.clientWidth + 1,
              );
            });
            cy.get(sel('bank-governance-confirmation')).scrollIntoView();
            cy.get(sel('bank-governance-confirm')).should('be.visible');
            cy.screenshot(`imp06-governance-${size.name}-confirmation`, {
              capture: 'viewport',
              overwrite: true,
            });
          }
          cy.viewport(1280, 900);
          cy.get(sel('bank-governance-cancel')).click();
          cy.get(sel('bank-governance-form')).should('not.exist');
          cy.get(sel('bank-governance-open')).should('be.focused');
          cy.get(sel('bank-archive-review')).click();
          cy.get('[role="dialog"]').should('contain.text', '25');
          cy.get(sel('bank-archive-cancel')).click();
          cy.then(() => {
            expect(patches).to.equal(0);
            expect(archives).to.equal(0);
          });
          cy.task<Snapshot>('bank-governance:snapshot', c, { log: false }).then(
            (after) => expect(after).to.deep.equal(before),
          );
          chooseOwner(c);
          cy.get(sel('bank-visibility')).select('PRIVATE');
          cy.get(sel('bank-governance-review')).click();
          cy.get(sel('bank-governance-cancel')).focus();
          pressKeyInChrome('Tab', true);
          cy.get(sel('bank-governance-confirm')).should('be.focused');
          pressEnterInChrome();
          cy.wait('@govern').its('response.statusCode').should('equal', 200);
          cy.get(sel('bank-governance-form')).should('not.exist');
          cy.get(detail)
            .should('contain.text', 'Administrador A')
            .and('contain.text', 'Privado');
          cy.task<{ action: string; count: number }[]>(
            'bank-governance:audit',
            c,
            { log: false },
          ).then((events) =>
            expect(
              events.reduce((total, event) => total + event.count, 0),
            ).to.equal(1),
          );
        },
      );
    });
  });

  it('IMP06-GOV-02 · Crear versión y archivar ejercicio usado → mantiene intento real y referencias previas', () => {
    prepare().then((c) => {
      cy.task<Result>('bank-governance:submit', c, {
        log: false,
        timeout: 60000,
      })
        .its('status')
        .should('equal', 201);
      cy.task<Snapshot>('bank-governance:snapshot', c, { log: false }).then(
        (before) => {
          expect(before.attempts!.count).to.equal(1);
          visit(c);
          let versions = 0;
          cy.intercept(
            'POST',
            `**/api/v1/exercises/${c.exerciseId}/versions`,
            (request) => {
              versions++;
              request.continue();
            },
          ).as('version');
          cy.get(sel('bank-version-open')).click();
          cy.get(sel('bank-version-form')).should('be.visible');
          cy.get('[name="title"]').clear().type('Versión administrativa E2E');
          cy.get('[name="tests.1.expected"]').clear().type('99');
          cy.get(sel('bank-version-submit')).click();
          cy.get('[role="dialog"] [role="alert"]').should('be.visible');
          cy.then(() => expect(versions).to.equal(0));
          cy.get('[name="tests.1.expected"]').clear().type('1');
          cy.get(sel('bank-version-submit')).click();
          cy.wait('@version').its('response.statusCode').should('equal', 201);
          cy.get(sel('bank-version-form')).should('not.exist');
          cy.get(detail)
            .should('contain.text', '26 de 26 versiones')
            .and('contain.text', 'Versión administrativa E2E');
          cy.get(sel('bank-archive-review')).click();
          cy.get('[name="reason"]').type(
            'Archivo conservando evidencia histórica',
          );
          cy.intercept(
            'POST',
            `**/api/v1/exercises/${c.exerciseId}/archive`,
          ).as('archive');
          cy.get(sel('bank-archive-confirm')).click();
          cy.wait('@archive').its('response.statusCode').should('equal', 200);
          cy.get(detail).should('contain.text', 'Archivado');
          cy.get(sel('bank-version-open')).should('not.exist');
          cy.get(sel('bank-governance-open')).should('not.exist');
          cy.task<Snapshot>('bank-governance:snapshot', c, { log: false }).then(
            (after) => expect(after).to.deep.equal(before),
          );
          cy.get('[data-testid="bank-uses-ready"]').should(
            'contain.text',
            '25',
          );
        },
      );
    });
  });

  it('IMP06-GOV-03 · Confirmar con ETag obsoleto → informa conflicto y recupera conservando la selección', () => {
    prepare().then((c) => {
      visit(c);
      chooseOwner(c);
      cy.task<Result>(
        'bank-governance:govern',
        { ...c, body: { visibility: 'PRIVATE' } },
        { log: false },
      )
        .its('status')
        .should('equal', 200);
      cy.intercept(
        'PATCH',
        `**/api/v1/exercises/${c.exerciseId}/governance`,
      ).as('govern');
      confirmGovernance();
      cy.wait('@govern').its('response.statusCode').should('equal', 412);
      cy.get('[role="dialog"] [role="alert"]').should('be.visible');
      cy.get(sel('bank-owner')).should('have.value', c.adminId);
      cy.contains('button', 'Cargar datos actuales').click();
      cy.get(sel('bank-governance-form')).should(
        'contain.text',
        'Datos actuales cargados',
      );
      cy.get(sel('bank-owner')).should('have.value', c.adminId);
      confirmGovernance();
      cy.wait('@govern').its('response.statusCode').should('equal', 200);
      cy.get(detail)
        .should('contain.text', 'Administrador A')
        .and('contain.text', 'Organización');
    });
  });

  it('IMP06-GOV-04 · Perder una respuesta confirmada y comprobar solicitud → mismo resultado, clave y auditoría', () => {
    prepare().then((c) => {
      const keys: string[] = [];
      const bodies: unknown[] = [];
      let discarded = false;
      cy.intercept(
        'PATCH',
        `**/api/v1/exercises/${c.exerciseId}/governance`,
        (request) => {
          keys.push(String(request.headers['idempotency-key']));
          bodies.push(request.body);
          request.continue();
        },
      );
      visit(c, (window) => {
        const original = window.fetch.bind(window);
        window.fetch = (input, init) =>
          original(input, init).then((response) => {
            if (
              !discarded &&
              init?.method === 'PATCH' &&
              String(input).endsWith(`/exercises/${c.exerciseId}/governance`) &&
              response.ok
            ) {
              discarded = true;
              throw new TypeError('Respuesta perdida después del commit TEST');
            }
            return response;
          });
      });
      chooseOwner(c);
      confirmGovernance();
      cy.contains('Conservamos la solicitud pendiente.').should('be.visible');
      cy.get(sel('bank-governance-cancel')).should('be.disabled');
      cy.get(sel('bank-governance-confirm'))
        .should('contain.text', 'Comprobar solicitud')
        .click();
      cy.get(sel('bank-governance-form')).should('not.exist');
      cy.get(detail).should('contain.text', 'Administrador A');
      cy.then(() => {
        expect(discarded).to.equal(true);
        expect(keys).to.have.length(2);
        expect(keys[0]).to.equal(keys[1]);
        expect(bodies[0]).to.deep.equal(bodies[1]);
      });
      cy.task<{ action: string; count: number }[]>('bank-governance:audit', c, {
        log: false,
      }).then((events) =>
        expect(
          events.reduce((total, event) => total + event.count, 0),
        ).to.equal(1),
      );
    });
  });

  it('IMP06-GOV-05 · Revocar acceso antes de confirmar → rechaza y retira los datos sin mutación', () => {
    prepare().then((c) => {
      visit(c);
      chooseOwner(c);
      cy.get(sel('bank-governance-review')).click();
      cy.task('bank-governance:revoke', c, { log: false });
      cy.intercept(
        'PATCH',
        `**/api/v1/exercises/${c.exerciseId}/governance`,
      ).as('denied');
      cy.get(sel('bank-governance-confirm')).click();
      cy.wait('@denied').then(({ response }) =>
        expect([403, 404]).to.include(response!.statusCode),
      );
      cy.get('[data-cy="exercise-bank-row"]').should('not.exist');
      cy.get(sel('exercise-bank-detail')).should('not.exist');
      cy.get(sel('bank-governance-form')).should('not.exist');
      cy.task('bank-governance:audit', c, { log: false }).should(
        'deep.equal',
        [],
      );
      cy.task(
        'bank-governance:revoke',
        { ...c, restore: true },
        { log: false },
      );
      visit(c);
      cy.get(detail).should('contain.text', 'Profesor A');
    });
  });
});
